s=s.replace('''export async function revokeSession(''','''/**
 * Moves every session that defaults to `orgId` — only `userId`'s sessions
 * when given — onto another org its user still belongs to, or onto none.
 * Called when a member is removed and when an org is deleted.
 */
export async function reassignActiveOrg(
  orgId: OrgId,
  userId: UserId | null = null,
): Promise<number> {
  const db = getDb();
  const rows = db
    .select({ id: sessions.id, userId: sessions.userId })
    .from(sessions)
    .where(
      and(
        eq(sessions.activeOrgId, orgId),
        userId === null ? undefined : eq(sessions.userId, userId),
      ),
    )
    .all();

  const stamp = toIsoTimestamp(new Date());
  const fallbackByUser = new Map<string, string | null>();

  for (const row of rows) {
    if (!fallbackByUser.has(row.userId)) {
      const next = db
        .select({ orgId: organizations.id })
        .from(members)
        .innerJoin(organizations, eq(organizations.id, members.orgId))
        .where(
          and(
            eq(members.userId, row.userId),
            eq(members.status, "active"),
            isNull(members.archivedAt),
            isNull(organizations.archivedAt),
          ),
        )
        .orderBy(asc(members.createdAt))
        .all()
        .find((candidate) => candidate.orgId !== orgId);
      fallbackByUser.set(row.userId, next?.orgId ?? null);
    }

    db.update(sessions)
      .set({ activeOrgId: fallbackByUser.get(row.userId) ?? null, updatedAt: stamp })
      .where(eq(sessions.id, row.id))
      .run();
  }

  return rows.length;
}

