cat > tests/services/zz-tmp-scenario.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);
import { hashToken } from "@/lib/hash";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

it("rejoin flow", async () => {
  const t = await createTenant("rejoin", "growth");
  const other = await createTenant("other", "growth");
  const before = await memberRepo.findMember(t.org.id, t.userIds.member);
  await memberRepo.insertMember(other.org.id, t.userIds.member, "member", null);
  await sessionRepo.createSession(t.userIds.member, "h1", "2099-01-01T00:00:00.000Z");
  const s = await sessionRepo.findSessionByTokenHash("h1");
  expect(s).not.toBeNull();
  const { getDb, sessions } = await import("@/server/db");
  const row = getDb().select().from(sessions).all()[0]!;
  await sessionRepo.setActiveOrg(row.id as never, t.org.id);

  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: before!.id });
  expect((await sessionRepo.findSessionByTokenHash("h1"))!.activeOrgId).toBe(other.org.id);
  expect(await notificationService.notify(t.org.id, "issue_assigned", [t.userIds.member], { title: "x", body: "y", href: "/", actorId: null })).toHaveLength(0);

  const inv = await invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "MEMBER@rejoin.test", role: "admin" });
  await expect(invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "member@REJOIN.test", role: "admin" })).rejects.toThrow();
  await expect(invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "Viewer@rejoin.test", role: "admin" })).rejects.toThrow();
  const resent = await invitationService.resendInvitation(t.actors.admin, inv.id);
  expect(resent.role).toBe("admin");
  expect(Date.parse(resent.expiresAt) - Date.now()).toBeGreaterThan(13.9 * 86400000);
  expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(1);

  // accept via raw token inserted
  await invitationRepo.revokeInvitation(t.org.id, resent.id);
  const raw = "z".repeat(32);
  await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "member@rejoin.test", role: "admin", expiresInDays: 14 }, t.userIds.admin, hashToken(raw));
  const stranger = await userRepo.insertUser({ email: "x@y.test", name: "x", passwordHash: "s" });
  await expect(invitationService.acceptInvitation(stranger.id, { token: raw })).rejects.toThrow(/different/);
  const m = await invitationService.acceptInvitation(t.userIds.member, { token: raw });
  expect(m.id).toBe(before!.id);
  expect(m.role).toBe("admin");
  expect(m.status).toBe("active");
  expect(m.invitedBy).toBe(t.userIds.admin);
  await expect(invitationService.acceptInvitation(t.userIds.member, { token: raw })).rejects.toThrow(/accepted/);
  expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(await memberRepo.countActiveMembers(t.org.id));
  expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
  expect(await notificationService.notify(t.org.id, "issue_assigned", [t.userIds.member], { title: "x", body: "y", href: "/", actorId: null })).toHaveLength(1);
});
EOF
npx vitest run tests/services/zz-tmp-scenario.test.ts 2>&1 | grep -v "npm warn" | tail -30; rm tests/services/zz-tmp-scenario.test.ts

